from safety_evals.loader import dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import monitor_flag_rate, pooled_flag_rate
from safety_evals.report import monitor_summary


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_none_is_not_flagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5


def test_monitor_flag_rate_empty():
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_equal_groups():
    groups = {"a": [{"flagged": True}, {"flagged": False}], "b": [{"flagged": True}, {"flagged": False}]}
    assert pooled_flag_rate(groups) == 0.5


def test_parse_transcript_log_one_line():
    assert parse_transcript_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "flagged": True}]


def test_parse_transcript_log_flag_values_and_skipped_lines():
    assert parse_transcript_log(
        ["", "  # comment", " x1 , 3 , 1 ", "x2,4,0", "x3,5,"]
    ) == [
        {"id": "x1", "day": 3, "flagged": True},
        {"id": "x2", "day": 4, "flagged": False},
        {"id": "x3", "day": 5, "flagged": None},
    ]


def test_parse_transcript_log_error_reports_original_line_number():
    try:
        parse_transcript_log(["# comment", "", "bad,line"])
    except ValueError as error:
        assert "line 3" in str(error)
    else:
        raise AssertionError("expected ValueError")


def test_dedupe_transcripts_keeps_duplicate_id_last():
    events = [
        {"id": "a", "day": 3, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "a", "day": 1, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[2], events[1]]


def test_daily_flag_counts_inclusive_range():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": None},
        {"id": "c", "day": 3, "flagged": True},
        {"id": "d", "day": 4, "flagged": True},
    ]
    from safety_evals.loader import daily_flag_counts

    assert daily_flag_counts(events, 2, 3) == [0, 1]
    assert daily_flag_counts(events, 3, 2) == []


def test_flags_in_window_uses_exact_number_of_entries():
    from safety_evals.metrics import flags_in_window

    assert flags_in_window([1, 2, 3], 2) == 5
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 5) == 6


def test_group_rate_and_summary_spec_details():
    from safety_evals.metrics import flag_rate_by_group
    from safety_evals.report import top_flagged_groups

    groups = {
        "z": [{"id": "z", "day": 1, "flagged": True}],
        "a": [{"id": "a", "day": 2, "flagged": True}],
        "empty": [],
    }
    assert flag_rate_by_group(groups) == {"a": 1.0, "empty": None, "z": 1.0}
    assert top_flagged_groups(groups, 3) == ["a", "z"]
    summary = monitor_summary(groups, 1)
    assert summary == {"rate": 1.0, "recent": 1, "groups": 2}


def test_monitor_summary_empty_groups():
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_monitor_summary_basic():
    e = [{"id": "a", "day": 1, "flagged": True}, {"id": "b", "day": 2, "flagged": False}]
    assert monitor_summary({"g": e}, 1)["groups"] == 1

